const fs=require('node:fs'),path=require('node:path');
async function main(){
 const pages=(await(await fetch('http://127.0.0.1:57221/json/list')).json()).filter(t=>t.type==='page'&&t.url.includes('/apps/pc-app/dist/ui/index.html'));
 if(pages.length!==1)throw Error('Unique original B2 renderer required');
 const expression=`(()=>{const rect=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}};const view=e=>({tag:e.tagName,role:e.getAttribute('role'),label:e.getAttribute('aria-label'),type:e.getAttribute('type'),value:e.getAttribute('role')==='slider'?e.getAttribute('aria-valuenow'):e.getAttribute('type')==='range'?e.value:null,text:e.getAttribute('role')==='combobox'?e.innerText:null,rect:rect(e)});return{route:location.hash,active:view(document.activeElement),controls:[...document.querySelectorAll('[role=slider],[role=combobox],input[type=range],[role=switch]')].map(e=>({...view(e),checked:e.getAttribute('aria-checked')})),messages:[...document.querySelectorAll('[role=status],[role=alert]')].map(e=>e.innerText),save:[...document.querySelectorAll('button')].filter(e=>e.innerText==='保存设置').map(e=>({text:e.innerText,disabled:e.disabled,rect:rect(e)}))}})()`;
 const ws=new WebSocket(pages[0].webSocketDebuggerUrl);
 const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{ws.close();reject(Error('Readonly timeout'));},10000);ws.onopen=()=>ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{returnByValue:true,expression}}));ws.onerror=()=>{clearTimeout(timer);reject(Error('Readonly connection failed'));};ws.onmessage=e=>{const r=JSON.parse(e.data);if(r.id!==1)return;clearTimeout(timer);ws.close();if(r.error||r.result?.exceptionDetails)reject(Error('Readonly DOM projection failed'));else resolve(r.result.result.value);};});
 const report={at:new Date().toISOString(),method:'Readonly public settings DOM and ARIA only; no business API/input/mutation/credential values',result};
 const output=path.join(__dirname,'cloudB2-settings-public-ui-'+process.argv[2]+'-20261026.json');fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({output,...report}));
}main().catch(e=>{console.error(e.message);process.exitCode=1;});
